import { readFileSync } from "node:fs";
import { describe, it, expect } from "vitest";
import {
    assertPublicInputs,
    aggregateCircuitPublicInputs,
    getCircuitMetadata,
    makeProofBundle,
} from "./proof-data";
import type { CircuitName, Hex } from "./circuit-types";

// Generated by the sibling protocol's executable helpers, independently of SDK formulas.
const vectors = JSON.parse(
    readFileSync(new URL("../../protocol/src/protocol-vectors.json", import.meta.url), "utf8")
).fixtures;
const aggregate = vectors.aggregateStatements as { innerVkCommitment: Hex; members: Hex[][] };
const zero = `0x${"00".repeat(32)}` as Hex;

describe("onchain statement binding", () => {
    for (const [count, capacity] of [
        [1, 14],
        [15, 56],
        [57, 112],
        [113, 168],
    ]) {
        const name = `transact_user_slots${capacity}` as CircuitName;
        it(`matches the independent slots${capacity} authorization digest`, () => {
            const inputs = vectors[`transact${count}`].userPublicInputs as Hex[];
            expect(() => assertPublicInputs(name, inputs)).not.toThrow();
            const changed = [...inputs];
            changed[changed.length - 1] = zero;
            expect(() => assertPublicInputs(name, changed)).toThrow("Authorization digest");
            const redirected = [...inputs];
            redirected[1] = zero;
            expect(() => assertPublicInputs(name, redirected)).toThrow("context address");
            const stale = [...inputs];
            stale[6 + 2 * capacity!] = zero;
            expect(() => assertPublicInputs(name, stale)).toThrow();
        });
    }

    it.each([4, 8, 12])("pins the current inner VK for %i-member aggregate statements", (count) => {
        const name = `transact_aggregate_14_${count}` as CircuitName;
        const inputs = [...aggregate.members.slice(0, count).flat(), aggregate.innerVkCommitment];
        expect(getCircuitMetadata(name).innerVkCommitment).toBe(aggregate.innerVkCommitment);
        expect(() => assertPublicInputs(name, inputs)).not.toThrow();
        expect(() => assertPublicInputs(name, [...inputs.slice(0, -1), zero])).toThrow(
            "inner verification key"
        );
        const changed = [...inputs];
        changed[58] = zero;
        expect(() => assertPublicInputs(name, changed)).toThrow("Authorization digest");
        const duplicate = [...inputs];
        duplicate.splice(59, 59, ...aggregate.members[0]!);
        expect(() => assertPublicInputs(name, duplicate)).toThrow("Duplicate aggregate");
    });

    it("builds circuit public inputs from current recursive bundles in order", async () => {
        // Dummy proof fields exercise structural checks only, never cryptographic verification.
        const members = await Promise.all(
            aggregate.members
                .slice(0, 4)
                .map((inputs) =>
                    makeProofBundle(
                        "transact_user_slots14",
                        "noir-recursive",
                        `0x${"00".repeat(458 * 32)}`,
                        inputs
                    )
                )
        );
        expect(await aggregateCircuitPublicInputs(members)).toEqual([
            ...aggregate.members.slice(0, 4).flat(),
            aggregate.innerVkCommitment,
        ]);
        await expect(aggregateCircuitPublicInputs(members.slice(0, 3))).rejects.toThrow(
            "4, 8 or 12"
        );
        await expect(
            aggregateCircuitPublicInputs([...members.slice(0, 3), members[0]!])
        ).rejects.toThrow("Duplicate aggregate");
        await expect(
            aggregateCircuitPublicInputs(members.map((m) => ({ ...m, target: "evm" })))
        ).rejects.toThrow("recursive slots14");
    });
});
